const scanChoices = [
  { id: 'purpose', label: 'Purpose', detail: 'What job is this choice supposed to perform?' },
  { id: 'capacity', label: 'Capacity', detail: 'What time, money, knowledge, and emotional room can I actually carry?' },
  { id: 'dependence', label: 'Dependence', detail: 'Who or what must keep working for this route to remain useful?' },
  { id: 'choice', label: 'Choice', detail: 'Which future options does this widen, narrow, or postpone?' },
];

const makeCheck = (prompt, correct, wrongOne, wrongTwo) => ({
  prompt,
  options: [
    { id: 'a', label: correct, isCorrect: true },
    { id: 'b', label: wrongOne, isCorrect: false },
    { id: 'c', label: wrongTwo, isCorrect: false },
  ],
});

const makeScenario = (prompt, best, weakOne, weakTwo) => ({
  prompt,
  options: [
    { id: 'a', label: best, strength: 'strong', feedback: 'This keeps the real purpose, tradeoff, and consequence visible before the decision moves.' },
    { id: 'b', label: weakOne, strength: 'developing', feedback: 'That answer notices one piece, but leaves the wider system hidden.' },
    { id: 'c', label: weakTwo, strength: 'developing', feedback: 'Speed or certainty cannot replace understanding of the choice being made.' },
  ],
});

const lesson = ({ title, sageOpen, story, understand, recognize, examine, mirror, workbook, growth, transition, check, scenario, sourceKeys = [], scan = scanChoices }) => ({
  title, sageOpen, story, understand, recognize, examine, mirror, workbook, workbookPrompt: workbook,
  growth, transition, check, scenario, sourceKeys, scan,
});

