export const rootNineOpening = {
  coreQuestion: 'How can ownership and investing widen future choice without turning hope into a promise or freedom into a number?',
  story: [
    'Beyond the Ownership Grove, the path rises toward a sunlit clearing where the oldest trees grow around a long wooden table. Their roots are visible above the soil, twisting around stones, water, and one another. Sage calls it the Long Horizon.',
    'Ivy arrives carrying an account statement and a new kind of pressure. She has learned enough to know she wants a future that is not entirely dependent on the next paycheck—but not enough to know whether she is building freedom or simply chasing an escape route with better vocabulary.',
    'Eli wants a plan that cannot disappoint him. Ivy wants a plan that changes her life now. Sage points to the trees. “Nothing living grows by pretending weather does not exist. We will look at ownership, time, risk, return, access, concentration, and the actual life beneath the number.”',
  ],
};

export const rootNineLessons = [
  lesson({ title: 'Freedom Is Not a Balance', sageOpen: 'Before we discuss wealth, name the freedom you want the money to support.', story: ['Ivy writes a number on the Grove table. Sage turns the chalk over. “What does the number let you do?”', 'The answers are not flashy: leave a harmful job, rest when sick, help a child without panic, survive a broken car, choose a smaller life without it becoming a crisis.', 'Eli realizes he has been measuring freedom by accumulation while quietly defining it as the ability to stop being cornered.'], understand: ['Financial freedom is a relationship between resources, obligations, choices, and time—not one universal number.', 'A goal becomes more useful when the learner can describe the life change it is meant to support.', 'Ownership is a possible tool for choice, not proof of worth or a guarantee of escape.'], recognize: ['People use “financial freedom” to mean flexibility, security, independence, status, or relief.', 'A large future balance can coexist with a fragile present or a life that still feels controlled.', 'A smaller goal can be deeply freeing if it removes a specific source of dependence.'], examine: ['What pressure is making the freedom story feel urgent?', 'Which obligation would change first if the goal were met?', 'Is the learner building a future or trying to make one number erase the present?'], mirror: 'The freedom I actually want money to support is…', workbook: 'Describe one freedom goal, the constraint it would loosen, the resources it may require, and what “enough for this purpose” would mean.', growth: 'I can define freedom by the choices it creates, not only by the balance it displays.', transition: 'The Grove gives them a purpose. Next they examine the claims that may carry it.', check: makeCheck('What should come before choosing an ownership route?', 'The life purpose, timing, access need, and tradeoff', 'The biggest recent return', 'The most impressive label'), scenario: makeScenario('Ivy wants a freedom number but cannot say what it changes. What should Sage ask?', 'What would become possible, and what would still remain difficult?', 'Which account has the largest balance?', 'How quickly can she announce the goal?'), sourceKeys: ['investor'] }),
  lesson({ title: 'What Does the Asset Actually Do?', sageOpen: 'An asset is not a personality. Describe the work it can and cannot perform.', story: ['At the next tree, every branch carries a different claim: a share of a company, a loan, a fund, a property interest, a tool, a piece of land.', 'Ivy keeps asking which branch grows fastest. Sage asks her to explain what produces value, who pays, what can interrupt it, and what she would own if the story went badly.', 'Eli finally says, “The asset is not the promise. It is the thing beneath the promise.” The clearing brightens as if the tree approves.'], understand: ['An asset is a claim or resource that may provide future economic benefit, but the result is uncertain.', 'Value can come from income, use, growth in demand, repayment, scarcity, productivity, or a combination.', 'The same word—investment—can hide very different rights, costs, and dependencies.'], recognize: ['This appears in securities, property, businesses, tools, collectibles, and pooled funds.', 'A price is what someone may pay now; it is not a guarantee of future value or income.', 'Tangible does not automatically mean understandable, liquid, or safe.'], examine: ['What creates value here?', 'What would make the claim weaker?', 'Who bears the maintenance, default, market, or management risk?'], mirror: 'A “good investment” story I have heard that needs a more exact explanation is…', workbook: 'Choose one asset and write: claim, value source, income source, costs, risks, access, dependence, and exit conditions.', growth: 'I can inspect the claim beneath the label.', transition: 'Now that they can name the claim, the next path tests return against risk.', check: makeCheck('What is the most useful first question about an asset?', 'What claim do I receive, and what can change its value?', 'How popular is it online?', 'How confident does the seller sound?'), scenario: makeScenario('A friend says a property “always goes up.” What belongs in Ivy’s examination?', 'Demand, costs, financing, maintenance, timing, and what happens if the price falls', 'Whether the property looks beautiful', 'Whether Ivy can repeat the slogan confidently'), sourceKeys: ['investor', 'risk'] }),
  lesson({ title: 'Risk Has a Clock', sageOpen: 'Risk changes meaning when the deadline changes.', story: ['A footbridge in the Grove has three signs: “needed next month,” “needed in five years,” and “needed when life changes.” The same storm reaches each sign differently.', 'Ivy wants every dollar working at maximum speed. Eli wants every dollar sitting still. Sage asks which dollar has a deadline, which can wait, and which is carrying a responsibility neither of them has named.', 'The lesson lands hard: a temporary decline can be survivable for one goal and devastating for another.'], understand: ['Time horizon changes the practical consequence of a loss, delay, or restricted access.', 'Volatility, permanent loss, inflation, default, liquidity, and behavior are different kinds of risk.', 'A long horizon can create room to wait, but it cannot make every risk irrelevant.'], recognize: ['The clock appears in emergencies, home purchases, education, retirement, caregiving, and career transitions.', 'People often call a choice safe because they have not yet needed to use the money.', 'Needing to sell at the wrong time can turn a temporary change into a permanent outcome.'], examine: ['When must this money work?', 'What would force a sale or withdrawal?', 'What behavior is likely when the value moves against the goal?'], mirror: 'The financial clock I most often ignore is…', workbook: 'Map one goal by date, access need, possible delay, possible loss, and what would force a change in plan.', growth: 'I can connect risk to the time and responsibility attached to the money.', transition: 'The bridge holds, but the wind reveals how much is resting on one support.', check: makeCheck('Why does a time horizon matter?', 'It changes how loss, delay, and access affect the goal', 'It guarantees a positive return', 'It removes the need to understand the asset'), scenario: makeScenario('Eli may need the money in eight months. What should remain visible?', 'The deadline, access need, possible loss, and consequence of being unable to wait', 'Only the long-term average return', 'The fact that other people are staying invested'), sourceKeys: ['risk', 'investor'] }),
  lesson({ title: 'Return Is Not the Same as Progress', sageOpen: 'A return is a result. Progress is whether the result served the life.', story: ['Ivy finds two trails. One climbs sharply but ends at a locked gate. The other rises slowly and reaches a place where she can actually live.', 'The numbers make the first trail look brilliant. The conditions make it less certain: fees, taxes, concentration, leverage, timing, and a need for access.', 'Sage does not tell them which trail to take. She makes them write down what counts as progress before they compare outcomes.'], understand: ['Return can be measured in price change, income, interest, or total value, but the measurement has limits.', 'A result can be positive and still fail the goal because of timing, access, cost, or risk.', 'Net progress requires attention to fees, taxes, inflation, and the money’s actual job.'], recognize: ['This appears when people celebrate gains without asking what they cost or whether they are repeatable.', 'A return comparison without the same time period, risk, and costs can mislead.', 'A lower visible return may be more useful when it keeps the goal reachable and the system stable.'], examine: ['What result is being measured?', 'What did the result require the person to tolerate or give up?', 'Does the result widen choice or merely create a more exciting number?'], mirror: 'A result I have mistaken for progress is…', workbook: 'Compare two fictional routes using gross return, costs, taxes, access, volatility, and the actual goal they serve.', growth: 'I can ask whether a result is useful before calling it progress.', transition: 'The next grove opens into a canopy where many branches share the same light.', check: makeCheck('What makes a return meaningful?', 'Its relationship to purpose, time, cost, risk, and access', 'Its size by itself', 'How exciting it sounds'), scenario: makeScenario('A high return requires large fees and a concentration in one asset. What should Ivy compare?', 'The full net result and what happens if the concentrated claim fails', 'Only the headline return', 'Whether it makes her look advanced'), sourceKeys: ['investor', 'risk'] }),
  lesson({ title: 'Diversification Is a Conversation', sageOpen: 'Many branches can reduce one kind of dependence without eliminating uncertainty.', story: ['The canopy holds many branches, but not all of them are separate. Some grow from the same trunk, drink from the same dry patch, or depend on the same gardener.', 'Ivy sees a basket and assumes it means protection. Eli sees five accounts and assumes he is diversified. Sage makes them trace the underlying exposure.', 'The basket is useful. It is not magic. The Grove is full of variety, but the wind can still reach the whole canopy.'], understand: ['Diversification spreads exposure across investments or risk sources; it does not remove loss or guarantee a result.', 'Two different-looking holdings may depend on the same sector, company, economy, geography, or behavior.', 'Diversification is a way to examine concentration, not a command to buy a particular product.'], recognize: ['It appears in funds, employer plans, property, income routes, and family resources.', 'Concentration can hide in one employer, one house, one client, one platform, or one story about the future.', 'Over-diversifying can also make a system hard to understand or manage.'], examine: ['What is actually exposed to the same event?', 'Which dependence would hurt most?', 'Does spreading the exposure support the goal or simply create more things to monitor?'], mirror: 'The dependence in my life that deserves a second branch is…', workbook: 'Draw a simple exposure map across income, cash, debt, housing, investments, and people. Circle shared risks.', growth: 'I can see concentration beneath the appearance of variety.', transition: 'The canopy spreads the risk, but the roots still need water, time, and attention.', check: makeCheck('What can diversification do?', 'Reduce some concentration without eliminating risk', 'Guarantee that no holding loses value', 'Make every investment identical'), scenario: makeScenario('Ivy owns several funds that all depend heavily on one industry. What is hidden?', 'The shared exposure beneath the separate fund names', 'The fact that she has multiple account numbers', 'A guarantee that the industry will recover'), sourceKeys: ['diversify', 'risk'] }),
  lesson({ title: 'Time Compounds More Than Money', sageOpen: 'Compounding is powerful, but it does not excuse poor fit or false certainty.', story: ['At the oldest tree, tiny rings become visible in the wood. Ivy counts the early years and gets impatient. Eli counts the later years and wants to skip the years that came before.', 'Sage points out the parts they cannot see in a chart: contributions, pauses, fees, taxes, inflation, changing returns, and the discipline to leave the money where its job requires.', 'Time can magnify growth. It can also magnify costs, concentration, and a mistake that no one revisits.'], understand: ['Compounding occurs when returns are added to a base that can itself produce future returns.', 'Time and consistent participation can matter, but outcomes remain uncertain and costs reduce what compounds.', 'A calculator illustrates a scenario; it does not forecast a personal result.'], recognize: ['Compounding appears in savings, debt, retirement, reinvested income, and long-term ownership.', 'High rates, fees, withdrawals, missed contributions, and inflation change the path.', 'The emotional difficulty is often staying engaged without turning a projection into a promise.'], examine: ['What assumptions make the projection work?', 'What could interrupt the time period?', 'Is the learner using a long horizon to understand risk or to avoid looking at it?'], mirror: 'The long-term assumption I need to make more honestly is…', workbook: 'Run three fictional projections with different time, contribution, fee, and return assumptions. Label every number as an assumption.', growth: 'I can use time as a lens without treating a projection as a promise.', transition: 'The tree has time, but the people beneath it still need to eat, move, and respond to weather.', check: makeCheck('What is true about compounding?', 'It can magnify growth and costs over time while outcomes remain uncertain', 'It guarantees a fixed future balance', 'It makes fees irrelevant'), scenario: makeScenario('A projection shows a large future balance. What should Ivy ask next?', 'Which assumptions, fees, interruptions, and access rules sit behind the projection?', 'Whether the chart looks impressive', 'Whether she can stop examining the plan'), sourceKeys: ['investor', 'retirement'] }),
  lesson({ title: 'Fees, Taxes, and the Quiet Leak', sageOpen: 'A cost does not have to be dramatic to change the future.', story: ['A small stream leaves the Grove table through a crack no one noticed. Ivy says it is too small to matter. Sage asks her to follow it for twenty years.', 'The stream carries account fees, transaction charges, management costs, taxes, maintenance, and the price of needing help.', 'Eli is embarrassed that he never asked. Sage is direct: “The point is not to shame the leak. The point is to make it visible before it becomes the river.”'], understand: ['Fees and taxes can reduce the amount available to grow or use.', 'The right comparison depends on the service received, the account rules, the holding, the jurisdiction, and the person’s purpose.', 'Low cost is not the only dimension; unexplained cost is the problem.'], recognize: ['Costs appear in accounts, funds, property, borrowing, professional services, and early exits.', 'A fee can be a percentage, a flat charge, a spread, a penalty, or an opportunity cost.', 'A person may pay for convenience or expertise without understanding what responsibility remains theirs.'], examine: ['Who is paid, how much, and for doing what?', 'What happens to the cost as the balance changes?', 'What does the learner believe the fee buys, and how could that be verified?'], mirror: 'The financial cost I am most likely to overlook is…', workbook: 'Make a cost inventory for one fictional future-money route: entry, ongoing, transaction, tax, access, service, and exit costs.', growth: 'I can look for quiet costs before they become a loud constraint.', transition: 'The leak is visible. The next clearing asks who is responsible for the route when conditions change.', check: makeCheck('Why should costs be included in an ownership decision?', 'They change the resources available for the goal', 'They matter only when the return is negative', 'They are automatically harmless when disclosed'), scenario: makeScenario('A provider explains the fee but not the service. What is the next question?', 'What responsibility, work, access, or accountability does the fee actually purchase?', 'Whether the provider seems friendly', 'Whether the fee can be hidden in the paperwork'), sourceKeys: ['investor', 'retirement'] }),
  lesson({ title: 'The Owner Still Has a Life', sageOpen: 'Ownership can create options and obligations at the same time.', story: ['Ivy sees a sign that says “passive.” Behind it are repairs, records, decisions, waiting, taxes, platform dependence, and a person who must notice when the plan stops matching reality.', 'Eli laughs. “That is a lot of activity for something called passive.”', 'Sage lets the word fall away. They list time, knowledge, cash, emotional capacity, ability to wait, and the willingness to change course. The asset does not get to borrow a life the owner does not have.'], understand: ['Ownership can require time, knowledge, monitoring, maintenance, communication, and capacity to absorb downside.', 'Delegating work changes who performs it; it does not remove dependence or responsibility to understand the arrangement.', 'An opportunity can be attractive and still exceed the owner’s present capacity.'], recognize: ['The load appears in property, direct business interests, collectibles, complex accounts, and concentrated positions.', 'Entry affordability is not the same as ongoing affordability.', 'People often price the asset and forget to price their own attention.'], examine: ['What work happens after the purchase?', 'What happens if time, health, income, or support changes?', 'Is the desire for “passive” driven by a real capacity need or by a promise of effortless escape?'], mirror: 'The ownership responsibility I would be most likely to underestimate is…', workbook: 'Create an ownership-load map with entry cost, ongoing cost, time, knowledge, dependence, access, and exit conditions.', growth: 'I can evaluate the life required to carry an opportunity.', transition: 'The Grove has shown them that freedom must fit inside a life, not float above it.', check: makeCheck('What belongs in an ownership-load check?', 'Time, knowledge, cash, dependence, responsibility, and downside capacity', 'Only the entry price', 'Only the possible upside'), scenario: makeScenario('Ivy can afford to buy but not maintain the asset. What does that reveal?', 'The opportunity may exceed her ownership capacity', 'The asset is automatically worthless', 'The maintenance can be ignored because ownership creates freedom'), sourceKeys: ['investor', 'risk'] }),
  lesson({ title: 'When the Market Shouts', sageOpen: 'A changing price can expose a belief before it proves anything.', story: ['The Grove market opens and every lantern changes color. Ivy feels the old urgency: act before the chance disappears. Eli feels the opposite urgency: exit before the world proves him wrong.', 'Sage asks what changed in the claim, what changed in the story, and what changed in them.', 'They practice separating information from noise, evidence from adrenaline, and a changed goal from a changed price.'], understand: ['Market movement is information about price and expectations, not a complete explanation of value or future outcome.', 'Behavior during gains and losses can become a financial risk of its own.', 'A decision may need review when facts or goals change, not simply when emotion becomes loud.'], recognize: ['This appears in headlines, social media, account alerts, family conversations, and sudden opportunities.', 'Fear and excitement can both make a person abandon the purpose that started the choice.', 'A plan that cannot explain what would trigger review may be a hope wearing paperwork.'], examine: ['What changed: the asset, the facts, the goal, or the feeling?', 'What decision rule was understood before the emotion arrived?', 'What would be evidence of a true mismatch rather than ordinary uncertainty?'], mirror: 'When money moves, the story I tell myself first is…', workbook: 'Write a calm review protocol for a fictional holding: facts to check, questions to ask, events that matter, and actions not to take impulsively.', growth: 'I can notice market emotion without handing it the steering wheel.', transition: 'The lights quiet. At the final table, they must connect the future to the present it depends on.', check: makeCheck('What should a changing price trigger first?', 'Questions about facts, purpose, time, and the original decision', 'An automatic action', 'A conclusion that the whole plan is a failure'), scenario: makeScenario('Ivy feels panic during a decline. What is the strongest first move?', 'Separate market movement from goal, facts, time horizon, and actual capacity', 'Check the price every minute', 'Copy the loudest reaction around her'), sourceKeys: ['risk', 'investor'] }),
  lesson({ title: 'Freedom Is Built Across Roots', sageOpen: 'A future claim cannot carry a present system that has been ignored.', story: ['The Long Horizon table connects to every Root they have already visited. Income feeds it. Cash flow opens or closes it. Debt pulls on it. Protection keeps one storm from taking the whole tree.', 'Ivy wants ownership to solve the places where the present feels tight. Sage does not shame the desire. She makes the connections visible.', 'Eli sees the difficult truth: investing is not a separate identity. It is one decision inside a life with bills, bodies, work, relationships, emergencies, and limits.'], understand: ['Ownership and investing interact with income, cash flow, debt, reserves, protection, health, and time.', 'Financial independence is partly a capacity question: what can the person carry, wait for, understand, and revise?', 'A mathematically promising path can be practically unstable when the surrounding roots are weak.'], recognize: ['This appears when future money is asked to rescue present shortfalls or when every future decision is delayed until life is perfect.', 'The same route can fit one person’s capacity and exceed another’s.', 'Revisiting an ownership decision after a life change is a sign of responsibility, not failure.'], examine: ['What job is future money being asked to perform?', 'What happens during job loss, illness, caregiving, debt stress, or a major repair?', 'Which earlier Root must remain visible before this route moves forward?'], mirror: 'The present root I need to keep visible while I think about the future is…', workbook: 'Draw a connection map between income, cash flow, debt, protection, reserves, and one future ownership goal.', growth: 'I can connect future ownership to the present system that must support it.', transition: 'The final clearing is not a product shelf. It is a map of what the learner can now evaluate alone.', check: makeCheck('What makes an investing decision practical?', 'The future goal and the present system that supports it', 'Only the projected growth', 'Waiting until life has no uncertainty'), scenario: makeScenario('Ivy wants to invest money she may need for a fragile month. What must stay visible?', 'The cash-flow gap, future purpose, access need, and consequence of needing the money', 'The excitement of the opportunity', 'A universal rule that investing is always right'), sourceKeys: ['investor', 'risk'] }),
  lesson({ title: 'The Freedom Map', sageOpen: 'The final capacity is not knowing what to buy. It is knowing what you are choosing.', story: ['Ivy and Eli receive a blank Grove map. It has no highlighted route and no “best” tree. It has spaces for purpose, claim, time, risk, costs, access, dependence, evidence, and questions that are still unanswered.', 'Ivy wants to fill it with one bright line. Eli wants to leave it blank until certainty arrives. Sage places both hands on the map. “Choice does not require certainty. It requires enough understanding to see the decision and keep it revisable.”', 'They draw different routes for different futures. Some money stays accessible. Some may participate in long-term growth. Some choices remain open because the evidence is not ready. The map feels less dramatic than the promise—and far more like something they can live with.'], understand: ['A freedom map connects purpose, claim, time, risk, cost, access, capacity, dependence, evidence, and responsibility.', 'Informed choice can include pause, comparison, investigation, and revision.', 'Financial decision capacity grows when the learner can explain both the route and the uncertainty around it.'], recognize: ['This framework can examine traditional investments, property, businesses, pooled funds, cash, and non-owner paths to future security.', 'Unknowns are not an embarrassment; they are a signal about what to investigate before commitment.', 'A changed decision can reflect new information or a changed life rather than personal failure.'], examine: ['What did the bright story hide?', 'Which parts are known, assumed, unknown, or dependent on someone else?', 'What would make the learner revisit the route without shame or panic?'], mirror: 'The future I want ownership to support is… The questions I refuse to skip are…', workbook: 'Complete a freedom map for one real or fictional goal. Mark every field as known, assumed, unknown, or dependent.', growth: 'I can evaluate ownership as a path to choice—not a promise, identity, or escape hatch.', transition: 'The Long Horizon releases them back into the Grove. Root Ten will ask what happens when a future is shared.', check: makeCheck('What is Root Nine’s final capability?', 'Evaluate ownership choices independently with purpose, risk, cost, access, and responsibility in view', 'Choose the product Sage prefers', 'Avoid all uncertainty forever'), scenario: makeScenario('Ivy finishes the map with unanswered questions. What is an informed next step?', 'Separate knowns from unknowns, investigate what matters, and keep the choice revisable', 'Hide the questions so the decision feels complete', 'Choose the most exciting route to prove confidence'), sourceKeys: ['investor', 'diversify', 'risk', 'retirement'] }),
];

