export const rootTenLessons = [
  lesson({ title: 'A Household Is a System', sageOpen: 'Before assigning blame, learn how the household actually moves.', story: ['The Legacy House has many doors, but only one pantry. Money enters through different rooms and leaves through needs no single person can see.', 'Eli says their household is fine because the bills are paid. Ivy says it is not fine because every surprise becomes a private emergency.', 'Sage draws income, obligations, care, labor, authority, and information on the floor. The picture is uncomfortable—and finally shared.'], understand: ['A household financial system includes money, labor, time, care, authority, information, and risk.', 'A shared life can have unequal contribution without having unequal worth.', 'Clarity begins with visibility, not with a perfect split.'], recognize: ['This appears in couples, multigenerational homes, blended families, roommates, and informal support networks.', 'Unpaid care and invisible administration still affect capacity and dependence.', 'A household can be loving and financially unclear at the same time.'], examine: ['Who knows what?', 'Who decides what?', 'Who absorbs the consequence when the plan fails?'], mirror: 'The household role I carry that other people may not see is…', workbook: 'Map household income, recurring obligations, care labor, decision authority, and information gaps without assigning moral labels.', growth: 'I can see the household as a system instead of a set of isolated complaints.', transition: 'The map shows shared life. The next room asks who gets a voice in shared decisions.', check: makeCheck('What belongs in a household map?', 'Money, labor, care, authority, information, and risk', 'Only the person who earns the most', 'Only the monthly bills'), scenario: makeScenario('Eli says the system is fine because nothing is late. What is missing?', 'Whether the labor, stress, information, and emergency capacity are sustainable', 'A more impressive spreadsheet', 'A rule that the highest earner decides everything'), sourceKeys: ['consumer'] }),
  lesson({ title: 'Shared Money Needs Shared Language', sageOpen: 'A conversation is part of the financial infrastructure.', story: ['At the kitchen table, Ivy uses “ours” to mean the account. Eli uses “ours” to mean the responsibility. They have been arguing with different definitions.', 'Sage makes them name contribution, ownership, access, privacy, and decision rights separately.', 'The words do not solve the whole problem. They make the problem possible to solve without guessing.'], understand: ['Shared financial decisions require clear language about ownership, access, contribution, privacy, and authority.', 'Fairness is not always identical treatment; it depends on the responsibilities and agreements involved.', 'Silence is not neutral when one person is making decisions with information the others lack.'], recognize: ['This appears in joint accounts, shared bills, family support, caregiving, property, and informal loans.', 'People may share a home without sharing assets, debts, or legal authority.', 'A conversation can protect a relationship by making assumptions visible early.'], examine: ['What has actually been agreed?', 'What is being assumed because it feels obvious?', 'What would each person need to know to participate meaningfully?'], mirror: 'The money word in my household that needs a clearer definition is…', workbook: 'Write plain-language definitions for “ours,” “mine,” “shared responsibility,” “access,” and “decision.”', growth: 'I can replace financial guessing with shared language.', transition: 'The table has language. The next room asks what care asks people to carry.', check: makeCheck('Why does shared language matter?', 'It makes ownership, access, responsibility, and assumptions visible', 'It guarantees everyone will agree', 'It eliminates the need for boundaries'), scenario: makeScenario('Two people both say an account is “ours.” What should they clarify?', 'Who owns it, who can access it, who contributes, and who decides', 'Who feels more entitled to it', 'Who can avoid the conversation longer'), sourceKeys: ['consumer'] }),
  lesson({ title: 'Power Hides in Access', sageOpen: 'Access is not the same as authority, and authority is not the same as care.', story: ['One key opens the Legacy House. Another opens the records room. A third opens the account that pays for the care no one wants to discuss.', 'Ivy assumes the person who handles the paperwork should control the money. Eli assumes the person who earns it should control the choices.', 'Sage asks who can see, who can act, who can explain, who can challenge, and who is protected if the trusted person is unavailable.'], understand: ['Access, ownership, authority, and responsibility are distinct parts of a financial arrangement.', 'Concentration of control can create vulnerability even when the person holding it is trusted.', 'Clear permissions and records help a household respond when someone is ill, unavailable, or in conflict.'], recognize: ['This appears in accounts, property, caregiving, business interests, benefits, and digital services.', 'Financial abuse can occur through control, isolation, coercion, deception, or misuse of access.', 'Trust works better when it is supported by visibility and boundaries.'], examine: ['Who can act without the others knowing?', 'What happens if the person with access disappears or changes?', 'Is the arrangement based on informed consent or on convenience?'], mirror: 'The access or authority I have never clearly examined is…', workbook: 'Create a household access map: view, transact, approve, explain, challenge, and emergency backup.', growth: 'I can see how access and power shape financial safety.', transition: 'The records room opens into a hallway where care becomes a daily cost.', check: makeCheck('What is the central risk of concentrated access?', 'One person may control decisions and information without enough visibility or backup', 'That everyone will have too much information', 'That trust becomes unnecessary'), scenario: makeScenario('A caregiver handles every account and refuses to share records. What matters first?', 'The person needing care’s safety, informed authority, records, and backup access', 'Whether the caregiver is offended', 'Whether the arrangement looks efficient'), sourceKeys: ['consumer', 'ftc'] }),
  lesson({ title: 'Care Is Work Even When It Is Love', sageOpen: 'Love can explain why care matters. It cannot make the labor costless.', story: ['In the Legacy House, one room is always warm because someone keeps carrying wood. That person is Ivy’s sister, who has reduced work hours to care for their mother.', 'Everyone calls her generous. No one has asked what the lost income, lost rest, and lost future contributions are doing to her.', 'Sage does not turn care into a transaction. She refuses to let affection erase the real resources being spent.'], understand: ['Caregiving can affect income, time, health, benefits, debt, savings, and future choices.', 'A family can value care while still naming the costs and distributing responsibility honestly.', 'Unpaid work is not financially invisible just because no invoice is sent.'], recognize: ['This appears in childcare, eldercare, disability support, transportation, household management, and crisis response.', 'Care responsibilities can arrive gradually and become permanent before anyone makes a plan.', 'Resentment often grows where sacrifice is praised but not acknowledged or shared.'], examine: ['Who is carrying the care and what is it displacing?', 'What support would reduce the load?', 'What promise is the family making without saying it aloud?'], mirror: 'The care labor in my life that deserves to be named is…', workbook: 'List care tasks, hours, out-of-pocket costs, lost opportunities, backup people, and the conversation that has been avoided.', growth: 'I can name care as a financial and human responsibility without reducing it to a price.', transition: 'The family can see the load. Next they plan for the moments when one person cannot carry it.', check: makeCheck('Why should caregiving be visible in financial planning?', 'It changes capacity, income, time, health, and future options', 'Because love is not real without a budget', 'Because every family must pay someone else'), scenario: makeScenario('A family praises one person for “handling everything.” What should they examine?', 'The actual load, lost capacity, backup plan, and shared responsibility', 'Whether praise replaces support', 'Whether the caregiver can simply work harder'), sourceKeys: ['consumer', 'dol'] }),
  lesson({ title: 'Dependents Are People, Not Categories', sageOpen: 'A dependent relationship includes needs, authority, dignity, and a future—not only a line item.', story: ['The house has a small room for a child, a quiet room for an elder, and a ramp that was added after someone’s body changed.', 'Ivy sees expenses. Eli sees obligations. Sage asks them to see people with changing needs, rights, voices, and limits.', 'The plan gets better when it stops treating dependence as a permanent identity and starts preparing for movement: more support, less support, different support.'], understand: ['Dependents may rely on others for money, care, access, decision support, or protection.', 'Needs and authority can change over time, and plans should be revisited.', 'Dignity means including the person in decisions to the extent possible.'], recognize: ['This appears in children, elders, disabled family members, temporary crises, and shared support networks.', 'A family can over-control someone while calling it protection.', 'A plan that ignores the dependent’s voice may create harm even if the money is available.'], examine: ['What does the person need, and what can they decide?', 'Who is authorized to act, and how is that checked?', 'What would a respectful transition look like if needs change?'], mirror: 'The dependent relationship I need to understand with more dignity is…', workbook: 'Build a needs-and-authority map for a fictional dependent: current needs, voice, support, boundaries, backup, and future changes.', growth: 'I can include people’s dignity and changing capacity in financial decisions.', transition: 'The room has a voice. The next path carries what families pass along on purpose—and by accident.', check: makeCheck('What should a dependent-care plan include?', 'Needs, voice, authority, support, boundaries, and change over time', 'Only the monthly cost', 'A permanent decision made once'), scenario: makeScenario('A family makes every decision for an adult relative without asking what they can decide. What is missing?', 'Capacity, consent, dignity, and the least restrictive support that fits the situation', 'More secrecy for convenience', 'A rule that protection requires total control'), sourceKeys: ['consumer'] }),
  lesson({ title: 'The Emergency Is Already Part of the Plan', sageOpen: 'A family plan is tested by interruption, not by a calm Tuesday.', story: ['The Legacy House loses power during a storm. The person with the account password is at the hospital. The backup contact is out of state. Everyone is loving, and nobody knows what to do.', 'Ivy reaches for old habits: solve the immediate problem and postpone the uncomfortable planning.', 'Sage gives them a short list: records, contacts, authority, cash access, medication, housing, communication, and the person who can say what the family agreed to.'], understand: ['Preparedness includes records, contacts, authority, access, communication, and resources for disruption.', 'An emergency plan should be usable by someone other than the person who created it.', 'Preparation reduces the number of decisions made under panic, but cannot remove every loss.'], recognize: ['This appears in illness, death, job loss, natural disaster, separation, identity theft, and sudden caregiving.', 'A plan hidden in one person’s memory is not a shared plan.', 'Privacy and preparedness must be balanced; sensitive information needs careful storage and boundaries.'], examine: ['What would fail first if the key person were unavailable?', 'Who needs to know what, and how would they verify it?', 'Which promise is impossible to keep without a backup?'], mirror: 'The family disruption I have not prepared to explain is…', workbook: 'Create a safe emergency index: people to call, documents to locate, authorities to verify, and the first three decisions to make.', growth: 'I can make a family plan usable under pressure.', transition: 'The storm passes. In the attic, the family finds boxes labeled inheritance, debt, and silence.', check: makeCheck('What makes an emergency plan useful?', 'It is findable, understandable, backed up, and matched to real authority', 'It is kept secret from everyone', 'It contains the most complicated instructions possible'), scenario: makeScenario('The only person who knows the plan is hospitalized. What should the family learn?', 'Which records, contacts, permissions, and next steps can be verified safely', 'How to guess the passwords', 'How to avoid discussing the gap'), sourceKeys: ['consumer', 'ftc'] }),
  lesson({ title: 'What We Inherit Besides Money', sageOpen: 'A family can pass down an account, a belief, a burden, or all three.', story: ['The attic is full of inherited instructions: never owe anyone, never talk about money, own a home at any cost, help family first, never trust a bank, always appear successful.', 'Ivy recognizes some of the rules in her own decisions. Eli recognizes the opposite rules in his.', 'Sage asks which lessons protected someone once, which lessons still fit, and which have become expensive loyalty tests.'], understand: ['Generational patterns include assets, debts, skills, beliefs, relationships, opportunities, and fears.', 'A financial belief can be adaptive in one context and restrictive in another.', 'Changing a pattern requires understanding its origin without treating history as destiny.'], recognize: ['Patterns appear in homeownership, debt, education, work, caregiving, secrecy, generosity, and risk.', 'People may reproduce a family rule while believing they are rebelling against it.', 'Naming a pattern creates room to choose whether to continue, revise, or end it.'], examine: ['What did this rule protect?', 'What does it cost now?', 'What new condition would make a different choice responsible rather than disloyal?'], mirror: 'A money rule I inherited that deserves examination is…', workbook: 'Write the rule, its origin story, the protection it once offered, the current cost, and the choice you want available now.', growth: 'I can honor history without letting it make every future decision.', transition: 'The attic opens toward the garden, where wealth must be transferred with more than good intentions.', check: makeCheck('What is a useful way to examine a family money rule?', 'Understand its origin, protection, current cost, and whether it still fits', 'Assume it is always true', 'Reject it without learning what it protected'), scenario: makeScenario('Ivy hears “people like us do not invest.” What should she ask?', 'What history created the rule, what it protects, and what evidence applies now', 'Whether she can shame the person who said it', 'Whether she should copy the opposite rule immediately'), sourceKeys: ['consumer'] }),
  lesson({ title: 'Assets Need a Destination', sageOpen: 'Transfer is not complete when someone says, “The family will know what to do.”', story: ['In the garden, every tree has a tag—but some tags are unreadable, some names are old, and one key opens a box nobody knew existed.', 'Eli assumes assets will naturally reach the right person. Ivy assumes a document will solve every relationship.', 'Sage makes them separate ownership, beneficiary designations, instructions, taxes, debts, care needs, and the possibility of disagreement.'], understand: ['Asset transfer depends on ownership, beneficiary designations, documents, law, taxes, debts, and the people involved.', 'A general family intention may not match the legal or practical path an asset will take.', 'Education about estate concepts is not the same as a personal legal conclusion.'], recognize: ['This appears in accounts, property, insurance, retirement plans, business interests, and digital assets.', 'Outdated beneficiaries and missing records can create conflict even in loving families.', 'Professional help may be needed for a situation’s facts, jurisdiction, and documents.'], examine: ['What is the asset, who owns it, and what document or rule controls it?', 'What happens if a beneficiary dies, disagrees, or cannot act?', 'What information should be shared now, and what belongs with a qualified professional?'], mirror: 'The transfer instruction my family would need to find is…', workbook: 'Make a fictional asset inventory with owner, intended recipient, document, location, update date, and question for a qualified professional.', growth: 'I can distinguish family intention from the mechanism that carries it.', transition: 'The garden has a map. The next room asks what conversations keep the map alive.', check: makeCheck('Why are beneficiary and ownership details important?', 'They can affect who receives an asset and how the transfer works', 'They guarantee no conflict', 'They matter only for wealthy families'), scenario: makeScenario('A retirement account still names an ex-partner. What belongs before assumptions?', 'Review the account rules, current documents, jurisdiction, and qualified professional questions', 'Assume the family promise overrides the form', 'Wait until a crisis to discover the answer'), sourceKeys: ['retirement', 'estate'] }),
  lesson({ title: 'Teach the Map, Not the Myth', sageOpen: 'The best inheritance is not a performance of certainty. It is a person who can ask questions.', story: ['Ivy imagines giving a child a house and calling the work complete. Sage asks what the child would understand about maintenance, taxes, debt, access, and the choices attached to the property.', 'Eli wants to hand down a rule: work hard, save, never complain. The Grove gives him a look that feels suspiciously like Sage.', 'They replace the myth with a map: how money moves, how decisions are made, how to verify, how to ask for help, and how to change course.'], understand: ['Financial capability can be transferred through explanation, practice, boundaries, and shared decision-making—not only through assets.', 'Teaching includes uncertainty, responsibility, and how to seek qualified help.', 'A family can build wealth and still pass along confusion if the system remains unspoken.'], recognize: ['This appears in allowances, conversations, shared accounts, caregiving, education funding, and inheritance.', 'Children and adults both learn from what families do, avoid, celebrate, and hide.', 'A practical lesson is stronger when it allows questions without shame.'], examine: ['What does the next person need to understand to carry this asset or responsibility?', 'Which part of the family story is too polished to be useful?', 'What knowledge should remain independent of any one person?'], mirror: 'The financial map I wish someone had taught me is…', workbook: 'Draft a one-page family teaching note: what the asset or responsibility is, how it works, what can change, who to ask, and what not to assume.', growth: 'I can pass along decision capacity, not just a financial story.', transition: 'The family now has a map. The final room asks what they are willing to say out loud.', check: makeCheck('What makes a family financial lesson durable?', 'It teaches how to understand, verify, question, and revise', 'It repeats one rule without context', 'It hides uncertainty to sound confident'), scenario: makeScenario('A parent wants to teach “never take risks.” What deeper lesson is needed?', 'How to identify, evaluate, carry, and revise risk in context', 'That all risk is reckless', 'That the child should never ask questions'), sourceKeys: ['consumer', 'investor'] }),
  lesson({ title: 'The Conversation Before the Crisis', sageOpen: 'The conversation you avoid becomes the decision someone else makes under pressure.', story: ['At the final table, Ivy and Eli each bring one sentence they have postponed: what happens if a parent needs care, what happens if one of them cannot work, what they want a child to inherit, and what they cannot promise.', 'The sentences are not elegant. Some are afraid. Some are angry. All are more useful than silence.', 'Sage keeps the lantern lit while they listen for the difference between a boundary, a request, a responsibility, and a fantasy.'], understand: ['Family financial communication is an ongoing practice of making roles, needs, limits, and decisions visible.', 'A conversation cannot guarantee agreement, but it can reduce avoidable surprise and isolation.', 'Shared decisions require respect for privacy, autonomy, and the authority that actually applies.'], recognize: ['This appears before marriage, parenthood, caregiving, inheritance, business involvement, separation, and major purchases.', 'People often wait for certainty before speaking, even when the conversation is what would create clarity.', 'A written follow-up can preserve what was agreed and what remains open.'], examine: ['What must be said before the next disruption?', 'Which feeling is being used to avoid a practical question?', 'What would respectful disagreement look like here?'], mirror: 'The family conversation I need to begin with honesty is…', workbook: 'Write an opening sentence, three questions, one boundary, and one next step for a conversation your family has postponed.', growth: 'I can start the conversation that makes a shared future more possible.', transition: 'The Legacy House opens its doors. Root Eleven waits in a working grove where value becomes something people create.', check: makeCheck('What is the purpose of a difficult family money conversation?', 'To make needs, roles, limits, and choices visible before pressure decides for everyone', 'To force identical beliefs', 'To avoid every future disagreement'), scenario: makeScenario('The family cannot agree on the whole plan. What is still possible?', 'Name what is agreed, what is not, who has authority, and the next specific conversation', 'Pretend agreement exists', 'End the relationship before asking any question'), sourceKeys: ['consumer', 'estate'] }),
  lesson({ title: 'The Legacy Map', sageOpen: 'Legacy is what continues because someone prepared it, taught it, or failed to name it.', story: ['The last map on the wall includes assets, care, skills, stories, obligations, people, documents, and unanswered questions.', 'Ivy wants the map to make the family safe forever. Eli wants it to prove they did enough. Sage brings them back to the tree: a living system needs review, sunlight, water, and room for new growth.', 'They mark what can be carried now, what needs help, what should not be passed on, and what future choice they want the next person to have.'], understand: ['Legacy includes resources, responsibilities, knowledge, relationships, patterns, and the choices made possible for the next person.', 'A family legacy plan must remain connected to changing people, laws, health, assets, and capacity.', 'The learner’s financial decision capacity includes making shared and long-range responsibilities visible.'], recognize: ['This map can be revisited after births, deaths, marriages, divorces, disability, job changes, asset changes, and new information.', 'A legacy is not measured only by how much is transferred.', 'The healthiest plan leaves room for autonomy, revision, and help.'], examine: ['What do we want to continue?', 'What do we want to stop?', 'What choice should be easier for the next person because we prepared?'], mirror: 'What I want my choices to make possible for the next person is…', workbook: 'Complete a legacy map with resources, responsibilities, people, documents, lessons, patterns to end, and choices to widen.', growth: 'I can treat legacy as a living system of responsibility and choice.', transition: 'The map points toward a gate in the trees. Root Eleven begins where the question changes from “What do we own?” to “What can we create?”', check: makeCheck('What is Root Ten’s final capacity?', 'Make shared and long-range choices with roles, care, authority, and transfer visible', 'Guarantee a conflict-free family', 'Transfer only the largest possible asset'), scenario: makeScenario('A legacy plan is complete but no one can explain it. What is unfinished?', 'The communication, teaching, access, and review needed for people to carry it', 'The family needs a more impressive title', 'The plan should be hidden to preserve surprise'), sourceKeys: ['consumer', 'estate', 'retirement'] }),
];

export const rootElevenProgressKey = 'rootwise_root_eleven_launch_progress_v1';
export const rootElevenParts = [
  { number: 1, title: 'See the Value', range: [1, 3] },
  { number: 2, title: 'Choose the Route', range: [4, 6] },
  { number: 3, title: 'Carry the Work', range: [7, 9] },
  { number: 4, title: 'Open the Gate', range: [10, 12] },
];
export const rootElevenOpening = {
  coreQuestion: 'How can I create value and widen opportunity without confusing entrepreneurship with identity, freedom with isolation, or a business idea with a sustainable system?',
  story: [
    'At the far edge of the Grove, sunlight pours through a stand of trees onto a clearing full of worktables. People are repairing, teaching, growing, designing, caring, researching, selling, organizing, and building things other people need.',
    'Ivy sees a gate marked BUSINESS and assumes it is the next level. Eli sees a list of risks and assumes it is a warning. Sage opens the gate but does not push them through.',
    '“Entrepreneurship is one route for creating value,” she says. “It is not a moral upgrade, a personality test, or a requirement to abandon employment, science, craft, caregiving, or ownership through other means. Learn the route before you romanticize it.”',
  ],
};

export const rootElevenLessons = [
  lesson({ title: 'Value Before the Business', sageOpen: 'A business begins with a problem worth solving, not a logo worth admiring.', story: ['The first clearing is full of beautiful signs and empty tables. Ivy wants to name her idea. Sage asks who needs it, what hurts, what changes, and why someone would exchange resources for the result.', 'Eli says, “What if we build it and they come?” The Grove answers with a long, awkward silence.', 'They begin with a person, a problem, a promise, and evidence. The idea gets smaller—and more real.'], understand: ['Value is created when a person, organization, or community receives a useful result relative to what it gives up.', 'A business idea is a hypothesis about a problem, a customer, a route, a cost, and a possible exchange.', 'Wanting to own a business is different from identifying a problem worth solving.'], recognize: ['Value creation appears in employment, professional work, trades, science, caregiving, creative work, and business ownership.', 'A product can be clever and still fail to solve a meaningful problem.', 'The customer’s reality matters more than the creator’s excitement.'], examine: ['Whose problem is this?', 'What does the person currently do instead?', 'What evidence would show the result is useful enough to exchange for?'], mirror: 'The problem I understand well enough to investigate is…', workbook: 'Write the person, problem, current workaround, proposed result, exchange, and three questions you would need to test.', growth: 'I can begin with value and evidence instead of identity and hype.', transition: 'The clearing has a problem worth testing. The next path asks which route can carry the value.', check: makeCheck('What should come before a business name?', 'A clear problem, person, useful result, and evidence worth testing', 'A large social following', 'A promise that everyone will want it'), scenario: makeScenario('Ivy loves an idea but cannot name who needs it. What should she do?', 'Investigate a specific person, problem, current workaround, and desired result', 'Spend more on branding', 'Assume the market will understand later'), sourceKeys: ['sba'] }),
  lesson({ title: 'Employment Is Not Failure', sageOpen: 'A route can be honorable, valuable, and strategic without being ownership.', story: ['The Grove path splits toward a hospital, laboratory, school, studio, corporate office, workshop, and independent stall. Ivy expects one path to glow brighter than the others.', 'Sage turns on all the lanterns. “A route is not a ranking. It is a set of tradeoffs.”', 'Eli sees stability, learning, benefits, autonomy, risk, scale, and responsibility distributed differently across the paths. The choice becomes more adult when no route has to be worshiped.'], understand: ['Value can be created through employment, professional practice, independent work, partnership, nonprofit work, or business ownership.', 'Each route trades among income, control, benefits, risk, learning, time, responsibility, and scale.', 'Entrepreneurship is not the only path to wealth, meaning, or influence.'], recognize: ['This appears in careers, contracting, licensing, research, management, skilled trades, creative work, and businesses.', 'People sometimes chase ownership to escape a bad job without examining whether the new route fits their capacity.', 'A job can be a platform for skill, capital, relationships, and future choice.'], examine: ['What does the person want more of: control, income, learning, flexibility, stability, or impact?', 'What would be gained and surrendered on each route?', 'Is the desire for ownership coming from value creation or from pain that needs another response?'], mirror: 'The work route that may fit my current capacity better than my ego admits is…', workbook: 'Compare employment, independent work, and ownership across income timing, benefits, control, risk, learning, responsibility, and exit options.', growth: 'I can choose a work route by fit and purpose, not status.', transition: 'The paths are legitimate. The next clearing asks what a customer or employer is actually exchanging for value.', check: makeCheck('What is true about entrepreneurship and employment?', 'Both can create value; each carries different tradeoffs and responsibilities', 'Ownership is always superior', 'Employment cannot build future choice'), scenario: makeScenario('Ivy wants to leave a harmful job immediately for a business idea with no evidence. What should stay visible?', 'The harm, the value hypothesis, the transition capacity, and other routes to safety', 'The idea must be right because the job is bad', 'That leaving is the only proof of courage'), sourceKeys: ['sba', 'dol'] }),
  lesson({ title: 'The Customer Is a Person', sageOpen: 'A market is made of people making choices under real constraints.', story: ['The third clearing has no empty demographic circles. It has people with budgets, habits, fears, deadlines, loyalties, and workarounds.', 'Ivy describes her imagined customer as “everyone who wants better.” Sage asks what they already use, what they can afford, and what would make them switch.', 'Eli discovers that being helpful is not the same as being chosen. The result has to fit the person’s life, not just the creator’s intention.'], understand: ['A customer has a problem, context, constraints, alternatives, and a reason to choose or reject a solution.', 'Demand is not the same as compliments, attention, or broad interest.', 'A useful offer must be understandable, reachable, deliverable, and worth the exchange to the customer.'], recognize: ['This appears in products, services, professional practices, nonprofit programs, and internal workplace solutions.', 'The buyer, user, payer, and decision-maker may be different people.', 'Listening and testing are forms of financial and operational evidence.'], examine: ['Who uses it, who pays, and who decides?', 'What would the person do without the offer?', 'What cost, trust, timing, or access barrier could prevent the exchange?'], mirror: 'The person whose real-world constraints I need to understand is…', workbook: 'Create a customer evidence sheet: problem, current alternative, budget or resource, decision-maker, trust barrier, desired result, and test question.', growth: 'I can treat the customer as a whole person instead of a target.', transition: 'The customer is visible. Now the Grove asks how the value travels from maker to user.', check: makeCheck('What is stronger evidence of demand?', 'A specific person choosing, using, paying for, or committing to a tested result', 'A compliment from a friend', 'A large audience that never acts'), scenario: makeScenario('People love Ivy’s concept but no one commits to try it. What should she learn?', 'Which problem, result, price, trust, or access condition remains unresolved', 'That the audience is simply wrong', 'That more excitement will solve the lack of evidence'), sourceKeys: ['sba'] }),
  lesson({ title: 'Price Is Part of the Promise', sageOpen: 'A price is not only what the creator wants. It is part of what the exchange has to carry.', story: ['At the market tables, Ivy sees the price as a verdict on her worth. Eli sees it as a number that must beat every competitor.', 'Sage makes them separate cost to deliver, value to the customer, access, alternatives, margin, taxes, time, and the promise being made.', 'The price becomes less personal and more accountable. It has a job: help the route survive while remaining honest about what the customer receives.'], understand: ['Price communicates an exchange but does not automatically equal value or profitability.', 'Sustainable pricing must account for delivery cost, time, overhead, taxes, risk, access, and the result promised.', 'Underpricing can hide unpaid labor and overpromising can create trust debt.'], recognize: ['This appears in services, products, freelance work, subscriptions, education, healthcare, and nonprofit funding.', 'A customer may value an outcome while still being unable or unwilling to pay the price.', 'Different routes can serve different customers without pretending the offer is identical.'], examine: ['What does the price need to cover?', 'What result is being promised and how will it be delivered?', 'What is the creator sacrificing to make the price look attractive?'], mirror: 'The work I have priced below its real cost is…', workbook: 'Build a simple price map with delivery time, materials, overhead, taxes, risk, customer result, access barrier, and minimum viable margin.', growth: 'I can connect price to value, cost, capacity, and honesty.', transition: 'The market has a price. The next path follows money through the route after the sale.', check: makeCheck('What belongs in a pricing decision?', 'Delivery cost, time, overhead, taxes, risk, access, and promised result', 'Only what competitors charge', 'Only what the creator wishes to earn'), scenario: makeScenario('Ivy is busy, underpaid, and calling the work “exposure.” What should she calculate?', 'The full time, cost, result, opportunity cost, and whether the exchange is sustainable', 'Whether exposure feels flattering', 'How to hide the unpaid labor'), sourceKeys: ['sba'] }),
  lesson({ title: 'Revenue Is Not Take-Home', sageOpen: 'Money entering the route is not the same as money available to the person.', story: ['The Grove market looks full after a busy day. Ivy celebrates the total. Eli points to the empty supply shed, the taxes envelope, the unpaid labor, and the customer refund waiting on the table.', 'Sage writes revenue, cost, gross result, operating expense, tax obligation, owner pay, and retained resources in a line.', 'The glamour leaves. The information stays.'], understand: ['Revenue is money received or earned before subtracting the costs and obligations needed to deliver the work.', 'Cash timing, profit, owner pay, taxes, reserves, and reinvestment are different questions.', 'A route can be busy and still financially fragile.'], recognize: ['This appears in freelance work, side income, businesses, commissions, contracting, and project work.', 'Growth can increase cash pressure when delivery costs arrive before payment.', 'Personal and business money can become confused when the system has no boundaries.'], examine: ['What money belongs to the work, the owner, taxes, future delivery, or someone else?', 'When does cash arrive and when do obligations arrive?', 'What would happen if one large customer paid late?'], mirror: 'The money number I have mistaken for income is…', workbook: 'Build a fictional monthly flow from revenue to delivery costs, overhead, taxes, owner pay, reserve, and retained resources.', growth: 'I can distinguish revenue from the money a person can actually use.', transition: 'The flow is visible. Now they examine the work and dependence required to keep it moving.', check: makeCheck('Why is revenue not the same as take-home pay?', 'Costs, taxes, timing, reserves, and other obligations still have to be carried', 'Revenue is always a personal asset', 'Taxes disappear when the work is small'), scenario: makeScenario('Ivy receives a large payment and wants to spend it all. What belongs first?', 'Separate delivery costs, taxes, owner pay, reserves, and retained resources before personal spending', 'Assume the payment is pure profit', 'Borrow against the excitement'), sourceKeys: ['sba', 'consumer'] }),
  lesson({ title: 'The Work Behind the Promise', sageOpen: 'A route is sustainable only if someone can keep delivering what was promised.', story: ['Ivy’s first test succeeds, and immediately the work multiplies. Every customer wants the personal version. Eli offers to automate everything by Friday.', 'Sage asks what must happen before, during, and after delivery; what breaks at higher volume; and who carries quality when the creator is exhausted.', 'The idea is not the system. The system is the repeated work that makes the idea true.'], understand: ['Operations include the repeatable activities, tools, people, quality controls, and decisions required to deliver value.', 'Scaling can increase reach while also increasing complexity, cost, dependence, and responsibility.', 'A promise that depends entirely on one exhausted person is a concentration risk.'], recognize: ['This appears in service businesses, product delivery, care work, education, software, farms, and creative practices.', 'Automation and delegation change the system but do not remove the need for oversight.', 'Capacity limits are evidence about the route, not a character flaw.'], examine: ['What must repeat for the promise to remain true?', 'Where is the single point of failure?', 'What quality or responsibility could be lost when the route grows?'], mirror: 'The part of my work that depends too heavily on one person is…', workbook: 'Map one delivery process with steps, time, tools, quality checks, backup, customer communication, and failure points.', growth: 'I can see the work required to keep a promise alive.', transition: 'The system is visible. The next path asks what responsibility follows when other people depend on it.', check: makeCheck('What does scaling change?', 'Reach, workload, cost, quality risk, dependence, and responsibility', 'Only the logo size', 'Nothing if demand is high'), scenario: makeScenario('Demand doubles but Ivy cannot deliver without working every waking hour. What does that show?', 'The offer has exceeded current capacity and needs a system or a different promise', 'That exhaustion proves commitment', 'That customers should simply wait forever'), sourceKeys: ['sba'] }),
  lesson({ title: 'Risk, Responsibility, and the Person Behind It', sageOpen: 'Creating value can widen choice while creating obligations to customers, workers, families, and the law.', story: ['The workshop clearing is bright until Sage points out the edges: contracts, safety, privacy, licensing, taxes, workers, refunds, records, and promises made in public.', 'Ivy wants to keep the idea flexible. Eli wants to avoid every responsibility by calling it a side project.', 'Sage is unimpressed by both strategies. A route does not become safer because its name is casual.'], understand: ['Independent work and business activity can create legal, tax, safety, contractual, privacy, and financial responsibilities.', 'The right structure and obligations depend on facts, jurisdiction, activity, and people involved.', 'Education can identify questions; it cannot replace qualified legal, tax, insurance, or regulatory guidance.'], recognize: ['This appears in hiring, contracts, customer data, regulated services, product claims, intellectual property, and public promises.', 'A casual arrangement can still create real consequences.', 'Responsibility grows when other people rely on the route.'], examine: ['Who could be harmed if the promise fails?', 'What rules, documents, insurance, or professional questions apply?', 'What risk is being carried personally because the system has not been designed?'], mirror: 'The responsibility I am most tempted to call “later” is…', workbook: 'Create a responsibility checklist: people affected, promises made, records, safety, privacy, taxes, contracts, licensing questions, and exit plan.', growth: 'I can see responsibility as part of value creation, not a punishment for trying.', transition: 'The gate has rules. The next clearing asks how value can grow without becoming a single fragile bet.', check: makeCheck('What should happen when other people rely on an offer?', 'The creator should identify responsibilities, risks, records, and applicable questions', 'The creator can avoid responsibility by staying informal', 'A promise is enough protection'), scenario: makeScenario('Ivy wants to provide a regulated service without checking requirements. What is the strongest pause?', 'Identify the activity, jurisdiction, licensing, documentation, and qualified guidance needed', 'Assume a disclaimer fixes everything', 'Start taking payment before asking'), sourceKeys: ['sba', 'consumer', 'ftc'] }),
  lesson({ title: 'More Than One Way to Build Wealth', sageOpen: 'Ownership is one route. Skill, reputation, employment, invention, and service can also widen future choice.', story: ['The final grove clearing shows a laboratory, a classroom, a clinic, a corporate office, a farm, a workshop, a nonprofit, and a small business. None is placed on a pedestal.', 'Ivy sees that her own future may include employment and ownership, investing and teaching, stable work and a creative project.', 'Sage tells them RootWise will not turn one route into a religion. The point is a wider field of choices.'], understand: ['Wealth can be built through income, saving, ownership, intellectual property, professional skill, business value, and long-term participation in systems.', 'Non-owner paths can create security, influence, and future choice.', 'The best route depends on purpose, capacity, opportunity, risk, and the value the person wants to create.'], recognize: ['This appears in careers, retirement plans, licensing, professional practice, business ownership, research, and community work.', 'People can own assets without owning a business, and create value without seeking ownership.', 'A portfolio of routes can reduce dependence but adds coordination and responsibility.'], examine: ['What kind of ownership or participation actually fits?', 'Which route creates the most useful learning or leverage now?', 'Is the learner expanding choices or simply collecting identities?'], mirror: 'The route to future choice I have undervalued is…', workbook: 'Compare three routes—employment, independent work, and ownership—against purpose, income timing, control, risk, learning, and future options.', growth: 'I can respect multiple routes to value and wealth.', transition: 'The routes do not compete for a crown. The last gate asks what the learner is ready to test responsibly.', check: makeCheck('What is Root Eleven protecting?', 'Multiple legitimate routes to value, wealth, and future choice', 'A requirement that everyone start a business', 'The idea that employment has no value'), scenario: makeScenario('Ivy wants to prove she is ambitious by quitting her job. What should she examine?', 'Whether the new route creates value and fits her purpose, evidence, capacity, and responsibilities', 'Whether quitting looks impressive', 'Whether ownership is morally superior'), sourceKeys: ['sba', 'dol', 'investor'] }),
  lesson({ title: 'Test Small Before You Bet Big', sageOpen: 'A test is not a lack of faith. It is a way to let reality participate.', story: ['Ivy wants a full launch: new equipment, a new identity, and a public promise that she will never go back.', 'Sage asks for one small test with a clear question. Eli objects that it is not impressive enough.', 'The test produces mixed evidence, which is exactly what a test is allowed to do. They learn what people use, what they ignore, what costs too much, and what must change.'], understand: ['Small tests can reduce uncertainty before a person commits more time, money, reputation, or dependence.', 'Evidence should answer a specific question rather than merely generate excitement.', 'A failed test can protect future choice when it prevents a larger unexamined bet.'], recognize: ['Testing appears in pilots, prototypes, interviews, preorders, sample services, experiments, and workplace projects.', 'A test needs a defined outcome, timeframe, cost, and rule for what the evidence means.', 'Not every question can be tested cheaply, and not every result is conclusive.'], examine: ['What decision will this test inform?', 'What would count as useful evidence?', 'What is the maximum loss the learner is willing to carry for the information?'], mirror: 'The small test that would teach me more than another month of planning is…', workbook: 'Design a low-cost test with a question, audience, offer, cost limit, measure, decision rule, and next step.', growth: 'I can buy information with a bounded experiment instead of gambling for certainty.', transition: 'The test has given them evidence. At the gate, they must choose a next step without pretending the evidence is complete.', check: makeCheck('What makes a small test useful?', 'A clear question, bounded cost, measure, timeframe, and decision rule', 'A large public launch', 'A result that confirms what the creator hoped'), scenario: makeScenario('Ivy gets mixed results from a pilot. What is the next capacity move?', 'Separate what the test answered, what it did not, and what should change before another commitment', 'Declare total failure', 'Ignore the evidence and spend more immediately'), sourceKeys: ['sba'] }),
  lesson({ title: 'The Business Hub Is a Door, Not a Destiny', sageOpen: 'The gate opens onto options. You are still allowed to choose the one that fits.', story: ['At the last gate, Ivy expects a graduation ceremony. Instead, there are questions carved into the wood: What value? For whom? Through which route? At what cost? With what responsibility? Under whose dependence?', 'Eli admits he still wants ownership—but now he can say why. Ivy admits she may begin with employment, a small test, or a skill she can build before taking on more risk.', 'Sage steps aside. The Grove does not choose for them. It has done something more useful: it made the choice harder to fake and easier to examine.'], understand: ['Entrepreneurship is a possible route for creating value, not a required identity or universal answer.', 'A responsible next step connects value, evidence, customer, route, price, cash flow, capacity, risk, and future choice.', 'The separate Business Hub can go deeper into business building after this doorway; Root Eleven prepares the learner to enter it with clearer questions.'], recognize: ['The framework can be revisited when an idea, job, opportunity, or responsibility changes.', 'A person can pause, revise, combine routes, or decide not to pursue ownership without losing ambition.', 'Financial decision capacity includes knowing what must be understood before a larger commitment.'], examine: ['What am I actually ready to test or learn?', 'What responsibility am I willing and able to carry?', 'Which route keeps the most honest future choices open?'], mirror: 'The next responsible door I am willing to open is…', workbook: 'Complete the Launch Map: problem, person, value, route, evidence, price, cash flow, capacity, responsibility, risk, and next test.', growth: 'I can approach entrepreneurship as a choice with responsibility—not a fantasy, escape, or status test.', transition: 'The grove gate opens. The eleven Roots now point toward a life the learner can question, build, protect, and choose.', check: makeCheck('What is Root Eleven’s final capacity?', 'Recognize entrepreneurship as one route while preserving other paths to value and wealth', 'Treat business ownership as the only successful future', 'Avoid all responsibility by staying small'), scenario: makeScenario('Ivy completes the Launch Map and still chooses employment for now. What does that mean?', 'She made an informed route choice that preserves future options and matches current capacity', 'She failed to become an entrepreneur', 'She should take the risk anyway to prove herself'), sourceKeys: ['sba', 'investor', 'consumer'] }),
];

function slugify(value) { return String(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }
function finalizeLessons(lessons, parts, prefix) {
  return lessons.map((item, index) => ({
    ...item,
    number: index + 1,
    displayNumber: `${prefix}.${index + 1}`,
    key: `${prefix}-${String(index + 1).padStart(2, '0')}-${slugify(item.title)}`,
    part: parts.find((part) => index + 1 >= part.range[0] && index + 1 <= part.range[1]),
  }));
}

export const rootNineCurriculum = finalizeLessons(rootNineLessons, rootNineParts, 'horizon');
export const rootTenCurriculum = finalizeLessons(rootTenLessons, rootTenParts, 'legacy');
export const rootElevenCurriculum = finalizeLessons(rootElevenLessons, rootElevenParts, 'launch');

export function rootFinalNarration(lesson) { return [lesson.sageOpen, ...lesson.story, ...lesson.understand, lesson.growth].join('\n\n'); }

export function resolveSources(lesson) {
  return (lesson.sourceKeys || []).map((key) => sources[key]).filter(Boolean);
}
